"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["92572"],{63851(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.nome_obrigatorio","status":422,"titulo":"Nome do modelo de formul\xe1rio \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.nome_obrigatorio","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) de um modelo de formul\xe1rio veio com o campo `nome` presente, mas vazio ou s\xf3 com espa\xe7os. O nome \xe9 o que identifica o modelo para quem o escolhe ao montar um processo.","Este c\xf3digo n\xe3o cobre o `nome` ausente do JSON nem enviado como `null`. Os dois corpos declaram o nome como texto n\xe3o anul\xe1vel, e o ASP.NET Core recusa o campo ausente ou nulo na valida\xe7\xe3o do modelo, com 400, antes de o pedido chegar \xe0s regras do Uni+ e, portanto, antes da busca do modelo. Essa recusa n\xe3o tem c\xf3digo do cat\xe1logo de erros. S\xf3 o nome presente e em branco responde 422 com o c\xf3digo desta p\xe1gina.","A recusa vem na lista `errors` da resposta, com `field` igual a `nome`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). O `nome` ausente ou nulo, recusado na leitura do corpo, vem antes da busca, mesmo com `{id}` inexistente."],"comoResolver":["Informe o nome do modelo, com at\xe9 200 caracteres, e repita o pedido. A atualiza\xe7\xe3o envia o nome mesmo que ele n\xe3o mude, porque substitui o descritivo e o conte\xfado por inteiro."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);